// WorkSpec 2.2 Constraints
module.exports = {
    "inventory.parts_non_negative": ctx => {
        for (const time of ctx.times()) {
            const quantity = ctx.getAt(time, "parts", "quantity");
            if (quantity < 0) return {
                time,
                objects: ["parts"],
                property: "quantity",
                observed: quantity,
                expected: { min: 0 },
                message: "Parts must never become negative."
            };
        }
        return null;
    }
};
